from __future__ import annotations
from typing import Optional
def first_repeat(word: str, k: int) -> Optional[tuple[int, int, str]]:
    seen: dict[str, int] = {}
    for j in range(len(word)-k+1):
        block = word[j:j+k]
        if block in seen:
            return seen[block], j, block
        seen[block] = j
    return None
encoded = [(i*i + i + 1) % 2 for i in range(20)]
decode: dict[int, str] = {0: "C", 1: "T"}
dna = "".join(decode[x] for x in encoded)
witness = first_repeat(dna, 4)
assert witness is not None
print(dna, witness)

