from __future__ import annotations
def threshold(q: int, k: int) -> int:
    if q < 0 or k < 0:
        raise ValueError("q and k must be nonnegative")
    return q ** k + k
for q in range(1, 5):
    print(q, threshold(q, 4))

from __future__ import annotations
from typing import Callable, Hashable, Optional, Sequence, TypeVar
A = TypeVar("A", bound=Hashable)
B = TypeVar("B", bound=Hashable)
def decoded_repeat(encoded: Sequence[A], decode: Callable[[A], B], k: int = 4) -> Optional[tuple[int, int, tuple[B, ...]]]:
    seen: dict[tuple[A, ...], int] = {}
    for j in range(len(encoded)-k+1):
        block = tuple(encoded[j:j+k])
        if block in seen:
            return seen[block], j, tuple(decode(x) for x in block)
        seen[block] = j
    return None

